INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 9, 'theory', 'Quiz: iproute2 and routing');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 0, 'The table has these routes: 10.0.0.0/8 with metric 1, 10.1.0.0/16 with metric 100 and default with metric 0. Which route will the kernel use for 10.1.2.3?', '["default, because its metric is 0", "10.0.0.0/8, because its metric is 1", "10.1.0.0/16, because its prefix is longest", "Any of the three, the choice is random"]', 2, 'The prefix length is compared first: /16 is longer than /8 and /0. The metric decides only between routes with the same prefix.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 1, 'ss -tln shows a LISTEN line on 127.0.0.1:6379. Where can connections to this port come from?', '["Only from the host itself", "From any network attached to the host", "Only from the same subnet as eth0", "Only from root processes"]', 0, 'The address 127.0.0.1 belongs to the loopback interface, so the socket accepts connections only from inside the host. Outside access needs 0.0.0.0, [::] or the address of an external interface.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 2, 'A server with two providers answers packets that came in over the second link through the first one, and the replies are lost. What fixes the forwarding?', '["Lower the metric of default in main to 0", "Enable net.ipv4.ip_forward", "Delete the proto kernel route", "A table with a default via the second provider and a rule from address lookup table"]', 3, 'Main has one default gateway, so the choice must depend on the source address: your own set of routes and an ip rule that sends packets with the second provider''s address into it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 3, 'What does a FAILED entry in ip neigh most often mean?', '["The address is used by two hosts at once", "No reply came to the ARP or neighbor discovery requests", "The administrator added the entry and it never ages", "The interface is in state LOWERLAYERDOWN"]', 1, 'FAILED is set when the maximum number of probes has gone out with no reply: the neighbor is off, in another network, or not answering. An entry that never ages is PERMANENT.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 9, 4, 'net.ipv4.conf.all.rp_filter = 2 and net.ipv4.conf.eth1.rp_filter = 0. Which reverse path mode applies on eth1?', '["Off, because eth1 has 0", "Strict", "Loose, because the larger of the two values is used", "The application chooses the mode"]', 2, 'The check on an interface uses the maximum of the all value and the interface''s own value: max(2, 0) = 2, which is loose mode.');
